import{_ as a,o as s,c as n,aa as t}from"./chunks/framework.D7Mdgkg-.js";const m=JSON.parse(`{"title":"Release Notes","description":"Feluqa's versioning scheme, support policy, Rust requirements, and release notes.","frontmatter":{"requestedLanguage":"fr","contentLanguage":"en","languageFallbackNotice":"Cette page n’est pas disponible en Français. La version en anglais est affichée.","sidebarTitle":"Releases","icon":"scroll-text","title":"Release Notes","description":"Feluqa's versioning scheme, support policy, Rust requirements, and release notes.","summary":"Explains Feluqa's versioning scheme before and after 1.0, the absence of an announced release cadence or support periods, and how release-specific Rust compiler requirements will be documented. It identifies the current development baseline without treating it as a published release or support promise.","date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","weight":1,"status":"Exploring","tags":["feluqa","release-notes","versioning"],"draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"},"search":false},"headers":[],"relativePath":"fr/prologue.md","filePath":"fr/prologue.md"}`),o={name:"fr/prologue.md"};function r(i,e,l,c,p,d){return s(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="release-notes" tabindex="-1">Release Notes <a class="header-anchor" href="#release-notes" aria-label="Permalink to &quot;Release Notes&quot;">​</a></h1><p>Each major documentation version has its own release notes. This page records the versioning scheme, support policy, Rust version requirements, and changes for the Feluqa release line covered by this documentation.</p><ul><li><a href="#versioning-scheme">Versioning Scheme</a></li><li><a href="#support-policy">Support Policy</a></li><li><a href="#current-development-baseline">Current Development Baseline</a></li></ul><h2 id="versioning-scheme" tabindex="-1">Versioning Scheme <a class="header-anchor" href="#versioning-scheme" aria-label="Permalink to &quot;Versioning Scheme&quot;">​</a></h2><p>Feluqa packages use <a href="https://semver.org/" target="_blank" rel="noreferrer">Semantic Versioning</a> and Cargo version constraints (<code>MAJOR.MINOR.PATCH</code>). Before 1.0, minor releases may include breaking changes while the public APIs are being established. Starting with 1.0, major releases may include breaking changes; minor releases add backward-compatible functionality, and patch releases contain compatible fixes.</p><p>Feluqa has not announced a release cadence. Do not infer a schedule from the numbering scheme.</p><p>When depending on Feluqa packages, choose a version constraint that matches the compatibility you need. Before 1.0, a constraint such as <code>0.2</code> stays within that minor line under Cargo&#39;s caret rules. For a stable major release, a constraint such as <code>^1.0</code> permits compatible minor and patch updates. Review the release notes and upgrade guidance before moving to a line that may contain breaking changes.</p><h2 id="support-policy" tabindex="-1">Support Policy <a class="header-anchor" href="#support-policy" aria-label="Permalink to &quot;Support Policy&quot;">​</a></h2><p>Feluqa has not announced bug-fix or security-support periods. Release and support dates will be added here once they are established. Development versions do not imply a support commitment.</p><p>Each published release will state its minimum supported Rust version (MSRV). The MSRV is the minimum compiler version the release promises to support; it is not necessarily the latest stable Rust version.</p><h2 id="current-development-baseline" tabindex="-1">Current Development Baseline <a class="header-anchor" href="#current-development-baseline" aria-label="Permalink to &quot;Current Development Baseline&quot;">​</a></h2><p>Feluqa is currently at <code>0.2.0</code>, and its development compiler baseline is Rust <code>1.88</code>.</p><ul><li>This documentation line covers package versions <code>&lt;=1.0.0</code>.</li><li>Cargo&#39;s package <code>version</code> field stores one exact version; a range belongs in a dependency requirement, not in that field. These development values are not a published release or a support commitment.</li></ul><p>The release cadence, verified release-wide MSRV, and support periods remain to be established.</p>',14)])])}const h=a(o,[["render",r]]);export{m as __pageData,h as default};
